def reverse_words(s):
    words = s.split()
    reversed_words = words[::-1]
    return ' '.join(reversed_words)

def intersection(a, b):
    set_b = set(b)
    result = []
    seen = set()
    for element in a:
        if element in set_b and element not in seen:
            result.append(element)
            seen.add(element)
    return result

def char_frequency(s):
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    return freq

def first_unique_char(s):
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    for index, char in enumerate(s):
        if freq[char] == 1:
            return index
    return -1

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            merged[-1][1] = max(last[1], current[1])
        else:
            merged.append(current)
    return merged

def max_subarray(numbers):
    max_current = max_global = numbers[0]
    for num in numbers[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current
    return max_global

def climb_stairs(n):
    if n == 0:
        return 1
    a, b = 1, 1
    for _ in range(1, n):
        a, b = b, a + b
    return b

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def longest_common_prefix(strings):
    if not strings:
        return ""
    min_len = min(len(s) for s in strings)
    for i in range(min_len):
        current_char = strings[0][i]
        for s in strings[1:]:
            if s[i] != current_char:
                return strings[0][:i]
    return strings[0][:min_len]
